```javascript
const MOD = 1000000007;

function add(a, b) {
    let s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

function sub(a, b) {
    let s = a - b;
    if (s < 0) s += MOD;
    return s;
}

function mul(a, b) {
    return (a * b) % MOD;
}

function pow_mod(a, e) {
    let res = 1;
    let cur = a % MOD;
    while (e > 0) {
        if (e & 1) res = mul(res, cur);
        cur = mul(cur, cur);
        e >>= 1;
    }
    return res;
}

function solve() {
    const input = require('fs').readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;
    const k = parseInt(input[0], 10);
    const w = parseInt(input[1], 10);

    if (k === 1) {
        if (w === 2) {
            console.log(2);
        } else {
            console.log(1);
        }
        return;
    }

    const k_mod = k % MOD;
    const k_minus_1_mod = (k - 1) % MOD;

    // Precompute powers of k up to w
    const maxPow = w;
    const pow_k = new Array(maxPow + 1);
    pow_k[0] = 1;
    for (let i = 1; i <= maxPow; i++) {
        pow_k[i] = mul(pow_k[i - 1], k_mod);
    }

    // Precompute powers of (k-1) up to w
    const pow_k1 = new Array(maxPow + 1);
    pow_k1[0] = 1;
    for (let i = 1; i <= maxPow; i++) {
        pow_k1[i] = mul(pow_k1[i - 1], k_minus_1_mod);
    }

    // Term C(w) = (k-1) * k^(w-1) * (k^(w-1) - (k-1)^(w-1))
    let termC = 0;
    if (w >= 2) {
        const part1 = sub(pow_k[w - 1], pow_k1[w - 1]);
        termC = mul(k_minus_1_mod, mul(pow_k[w - 1], part1));
    }

    // Sum S = sum_{L=w+1}^{2w-1} (k-1)^2 * k^(L-w-1) * (k^(w-1) - (k-1)^(w-1)) * (k^(2w-L) - (k-1)^(2w-L))
    // Let d = L - w, d from 1 to w-1
    // Term(d) = (k-1)^2 * k^(d-1) * D * (k^(w-d) - (k-1)^(w-d)) where D = k^(w-1) - (k-1)^(w-1)
    const D = sub(pow_k[w - 1], pow_k1[w - 1]);
    const k_minus_1_sq = mul(k_minus_1_mod, k_minus_1_mod);
    const inv_k = pow_mod(k_mod, MOD - 2);
    const inv_k1 = pow_mod(k_minus_1_mod, MOD - 2);

    let current_k_pow = 1; // k^0
    let current_k1_pow = 1; // (k-1)^0
    let sumS = 0;

    for (let d = 1; d <= w - 1; d++) {
        // term = (k-1)^2 * k^(d-1) * D * (k^(w-d) - (k-1)^(w-d))
        const part2 = sub(pow_k[w - d], pow_k1[w - d]);
        let term = mul(k_minus_1_sq, mul(current_k_pow, mul(D, part2)));
        sumS = add(sumS, term);

        current_k_pow = mul(current_k_pow, k_mod);
        current_k1_pow = mul(current_k1_pow, k_minus_1_mod);
    }

    let ans = add(termC, sumS);
    console.log(ans);
}

solve();
